package com.projexa.coaching.automation.service;
import com.projexa.coaching.automation.domain.AutomationEnums.*; import org.springframework.stereotype.Service;
@Service public class AutomationEngine { public boolean evaluate(Operator operator,Object actual,Object expected){ if(operator==Operator.IS_EMPTY)return actual==null||actual.toString().isBlank(); if(operator==Operator.IS_NOT_EMPTY)return actual!=null&&!actual.toString().isBlank(); if(actual==null)return false; int c=actual.toString().compareTo(String.valueOf(expected)); return switch(operator){case EQUALS->actual.toString().equals(String.valueOf(expected));case NOT_EQUALS->!actual.toString().equals(String.valueOf(expected));case GREATER_THAN->c>0;case LESS_THAN->c<0;case GREATER_THAN_OR_EQUAL->c>=0;case LESS_THAN_OR_EQUAL->c<=0;case CONTAINS->actual.toString().contains(String.valueOf(expected));case NOT_CONTAINS->!actual.toString().contains(String.valueOf(expected));default->false;}; } }